<?php require __DIR__.'/app/bootstrap.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$phone=trim($_POST['phone']??'');$password=$_POST['password']??'';$profession=trim($_POST['profession']??'');if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8){flash('error','Revisa nombre, correo y contraseña (mínimo 8 caracteres).');redirect('reviewer-register.php');}try{db()->beginTransaction();$st=db()->prepare("INSERT INTO users(uuid,name,email,phone,password_hash,role,status,email_verified_at,created_at,updated_at) VALUES(UUID(),?,?,?,?, 'reviewer','active',NOW(),NOW(),NOW())");$st->execute([$name,$email,$phone,password_hash($password,PASSWORD_DEFAULT)]);$uid=db()->lastInsertId();$st=db()->prepare("INSERT INTO reviewer_profiles(user_id,profession,license_number,organization_name,verification_status,created_at) VALUES(?,?,?,?, 'pending',NOW())");$st->execute([$uid,$profession,trim($_POST['license_number']??''),trim($_POST['organization_name']??'')]);db()->commit();flash('success','Cuenta creada. Ya puedes iniciar sesión.');redirect('login.php');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();flash('error','No se pudo crear la cuenta. El correo podría estar registrado.');redirect('reviewer-register.php');}}render_header('Registro de revisor');?>
<div class="container py-4" style="max-width:700px"><h1>Registrarme como revisor</h1><p class="text-muted">Una cuenta registrada no equivale automáticamente a profesional verificado.</p><form method="post"><?=csrf_field()?><div class="form-section"><div class="row g-3"><div class="col-md-6"><label class="form-label">Nombre completo *</label><input class="form-control" name="name" required></div><div class="col-md-6"><label class="form-label">Teléfono *</label><input class="form-control" name="phone" required></div><div class="col-md-6"><label class="form-label">Correo *</label><input class="form-control" type="email" name="email" required></div><div class="col-md-6"><label class="form-label">Contraseña *</label><input class="form-control" type="password" name="password" minlength="8" required></div><div class="col-md-6"><label class="form-label">Profesión</label><input class="form-control" name="profession" placeholder="Ingeniero civil, arquitecto..."></div><div class="col-md-6"><label class="form-label">Matrícula profesional</label><input class="form-control" name="license_number"></div><div class="col-12"><label class="form-label">Organización / empresa</label><input class="form-control" name="organization_name"></div></div></div><button class="btn btn-primary btn-lg w-100">Crear cuenta</button></form></div><?php render_footer();?>